+        // The run ended aborted — not hung, not errored.
+        final last = agent.state.messages.last;
+        expect(
+          last,
+          isA<AssistantMessage>().having(
+            (m) => m.stopReason,
+            'stopReason',
+            StopReason.aborted,
+          ),
+          reason: 'withGuard=$withGuard',
+        );
+      }
+    },
+  );
+}
