  const SpillsConfig({
    this.enabled = true,
    this.threshold = 8192,
    this.headChars = 2000,
    this.tailChars = 2000,
    this.userThreshold = defaultUserSpillThresholdBytes,
    this.userFraction = defaultUserSpillWindowFraction,
    this.notes = const [],
  });

