      ),
      emit: _processEvent,
      streamFunction: streamFunction,
      toolExecutor: toolExecutor,
      cancelToken: token,
    );
  });
}

Future<void> _runContinuation() {
  return _runWithLifecycle((token) {
    return runAgentLoopContinue(
