    io.writeln(
      tuiDim(
        'tty: ${drifted.join(', ')} re-enabled by a child process — '
        'cleared (Ctrl+S steering safe)',
      ),
    );
  }

  /// Persists an idle-steer record, then marks it delivered (the run
  /// that [text] started IS the delivery — no FIFO, no boundary wait).
