List<String> _wrapDoc(String text, [int width = 76]) {
  final lines = <String>[];
  var current = '';
  for (final word in text.split(' ')) {
    if (current.isEmpty) {
      current = word;
    } else if (current.length + 1 + word.length <= width) {
      current = '$current $word';
    } else {
      lines.add(current);
      current = word;
    }
  }
  if (current.isNotEmpty) lines.add(current);
  return lines;
}

