  String toYaml() {
    if (enabled &&
        threshold == 8192 &&
        headChars == 2000 &&
        tailChars == 2000 &&
        userThreshold == defaultUserSpillThresholdBytes &&
        userFraction == defaultUserSpillWindowFraction) {
      return '';
    }
    final buffer = StringBuffer('spills:\n');
    if (!enabled) buffer.write('  enabled: false\n');
