    if (headChars != 2000) buffer.write('  headChars: $headChars\n');
    if (tailChars != 2000) buffer.write('  tailChars: $tailChars\n');
    if (userThreshold != defaultUserSpillThresholdBytes) {
      buffer.write('  userThreshold: $userThreshold\n');
    }
