}

/// Start a new prompt from a batch of messages.
Future<void> promptMessages(List<Message> messages) {
  if (_activeRun != null) {
    throw StateError(
      'Agent is already processing a prompt. Use steer() or followUp() to '
      'queue messages, or wait for completion.',
